  on<_RequestT extends EventHandlerRequest = EventHandlerRequest>(
    method: HTTPMethod | Lowercase<HTTPMethod> | "",
    route: string,
    handler: HTTPHandler<_RequestT>,
    opts?: RouteOptions,
  ): this;

